{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "The highest-transfer analogue, a benzamidine-containing dicarboxylate, had absolute oral bioavailability judged not high enough for oral use in humans, directly supporting low F for the query's benzamidine-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Perindoprilat, a peptide-like dicarboxylic acid with very high transfer, showed 19±7% absolute oral bioavailability in healthy subjects, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Revefenacin had <3% absolute oral bioavailability in humans, supporting low F, though with lower transferability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Avanafil showed 8–10% oral bioavailability in humans, below threshold, adding low-F support at lower transfer.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Sulpiride showed 27–34% absolute oral bioavailability, above the 20% threshold; this is contradictory evidence, but its benzamide/sulfonamide structure lacks the benzamidine-carboxylate ion-pairing of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C22"],
      "claim": "A folate-like analogue had 41±18% absolute bioavailability, providing high-F contradictory evidence with high transfer, but its structural class is remote from the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The most structurally relevant high-transfer evidence (benzamidine-containing analogue and peptide-like diacid) indicates low oral bioavailability, and additional low-F drugs support this. High-F analogues are structurally distant or borderline, so low is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "High-transfer high-F analogues are structurally distant (folate-like, small thiol), limiting confidence in their applicability.",
    "Sulpiride's quantitative F is above threshold but often described as low, creating ambiguity around threshold interpretation.",
    "Fasted-state-specific data for the query are not directly available; most evidence comes from varied dosing conditions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

